export const TOOL_FILES = {"founders.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"robots\" content=\"noindex\">\n<title>Founder's Lantern setup</title>\n<style>\n:root{--ink:#1a1c2c;--bg:#0f1020;--panel:#20243a;--line:#3d4a66;--text:#eef1f5;--muted:#a9bdcc;--gold:#ffcd75;--green:#a7f070;--red:#ef7d57;--flame:#b98cff}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\nmain{max-width:640px;margin:0 auto;padding:20px 16px 60px}h1{color:var(--flame);font-size:26px;margin:0 0 4px}h2{font-size:18px;margin:26px 0 6px;color:var(--gold)}\np,li{color:var(--muted)}b{color:var(--text)}label{display:block;margin:12px 0 4px;font-weight:600}\ninput,textarea{width:100%;font:15px ui-monospace,Menlo,monospace;padding:10px;background:var(--panel);color:var(--text);border:2px solid var(--line)}\nbutton{font:600 16px system-ui;padding:12px 16px;margin-top:12px;background:#3b5dc9;color:#fff;border:2px solid var(--ink);cursor:pointer;width:100%}button:disabled{opacity:.5}button.alt{background:#333c57}\n.box{background:var(--panel);border:2px solid var(--line);padding:12px 14px;margin:10px 0;word-break:break-all}.ok{color:var(--green)}.bad{color:var(--red)}code{color:var(--gold)}\nspan.w{display:inline-block;margin:2px 8px 2px 0;color:var(--text)}span.w small{color:var(--muted)}img.art{width:140px;height:140px;image-rendering:pixelated;border:2px solid var(--flame);float:right;margin:0 0 10px 12px}\n</style></head><body><main>\n<p style=\"margin:0 0 10px\"><a href=\"/tools\" style=\"color:#a9bdcc\">← Owner tools</a></p>\n<img class=\"art\" src=\"/api/founders?img=1\" alt=\"\">\n<h1>Founder's Lantern setup</h1>\n<p>For the Lanternhold owner. Open this page in your wallet app's browser (MetaMask, Rabby…) on Robinhood Chain. The wallet you deploy with becomes the collection's owner and receives royalties (5%).</p>\n<div class=\"box\" id=\"who\">Not connected.</div>\n<button id=\"conn\">Connect wallet</button>\n\n<h2>1. Deploy the collection</h2>\n<p>Creates the Founder's Lantern NFT contract: 2,222 in all. Any hero can mint their own number, once, one per wallet, free (gas only). 1,222 are open to every hero first-come; 1,000 are held for the X giveaway winners you add below.</p>\n<label for=\"sig\">Signer address (the wallet whose private key is FOUNDERS_SIGNER_KEY in Vercel; you can reuse the rewards signer)</label><input id=\"sig\" placeholder=\"0x…\">\n<label for=\"openCap\">Open pool (any hero)</label><input id=\"openCap\" value=\"1222\">\n<label for=\"resvCap\">Giveaway pool (held for winners)</label><input id=\"resvCap\" value=\"1000\">\n<label for=\"base\">Token metadata address (the token number is added to the end)</label><input id=\"base\" value=\"\">\n<button id=\"dep\" disabled>Deploy the collection</button>\n<div class=\"box\" id=\"depOut\" hidden></div>\n\n<h2>2. Open the mint</h2>\n<p>In Vercel → Settings → Environment Variables: <code>FOUNDERS_CONTRACT</code> = the collection's address, and <code>FOUNDERS_SIGNER_KEY</code> = the signer's private key (mark it <b>Sensitive</b>; if you leave it out, <code>CLAIM_SIGNER_KEY</code> is used). Redeploy, then open <code>/api/health</code>: <code>founders.mint</code> should be <code>true</code>, and <code>founders.heroNumbers</code> and <code>founders.giveaway</code> <code>ok</code> (run <code>supabase/founders-giveaway.sql</code> once).</p>\n\n<h2>3. Owner controls</h2>\n<label for=\"nft\">Collection address</label><input id=\"nft\" placeholder=\"0x…\">\n<div class=\"box\" id=\"stat\">–</div>\n<button id=\"refresh\" class=\"alt\" disabled>Refresh status</button>\n<button id=\"pause\" class=\"alt\" disabled>Pause / unpause minting</button>\n<label for=\"end\">End the mint at (your local time; empty = no end)</label><input id=\"end\" type=\"datetime-local\">\n<button id=\"setEnd\" class=\"alt\" disabled>Set the end time</button>\n<label for=\"moveN\">Move unclaimed giveaway spots to the open pool</label><input id=\"moveN\" placeholder=\"e.g. 50\">\n<button id=\"move\" class=\"alt\" disabled>Move spots</button>\n<div class=\"box\" id=\"ctlOut\" hidden></div>\n\n<h2>4. X giveaway winners</h2>\n<p>Add the winners by hero name (one per line, or separated by commas). A winner's mint comes from the giveaway pool, so they're sure of a Lantern even once the open pool runs out. Nothing in the game says the pools exist; winners just see \"giveaway winner\" on their own Founder's Lantern screen.</p>\n<div class=\"box\" id=\"wCount\">–</div>\n<label for=\"wNames\">Hero names</label><textarea id=\"wNames\" rows=\"4\" placeholder=\"Hero names…\"></textarea>\n<button id=\"wAdd\">Add winners</button><button id=\"wDel\" class=\"alt\">Remove these names</button>\n<div class=\"box\" id=\"wList\" style=\"max-height:260px;overflow:auto\"></div>\n</main><script src=\"/tools/founders.js\"></script></body></html>\n","founders.js":"// Owner tool: deploy the Founder's Lantern collection (contracts/LanternFounders.sol) and control the mint, from the owner's wallet.\n(function () {\n  var BYTECODE = '', CHAIN = '0x1237', $ = function (id) { return document.getElementById(id); };\n  var pv = window.ethereum, from = null;\n  var hex32 = function (h) { return h.replace(/^0x/, '').toLowerCase().padStart(64, '0'); };\n  var num32 = function (n) { return BigInt(n).toString(16).padStart(64, '0'); };\n  var isAddr = function (a) { return /^0x[0-9a-fA-F]{40}$/.test(a); };\n  var show = function (id, html, cls) { var e = $(id); e.hidden = false; e.className = 'box ' + (cls || ''); e.innerHTML = html; };\n  var esc = function (s) { return String(s).replace(/[&<>\"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]; }); };\n  function str(s) { var b = new TextEncoder().encode(s), h = ''; for (var i = 0; i < b.length; i++) h += b[i].toString(16).padStart(2, '0'); return num32(b.length) + h.padEnd(Math.ceil(b.length / 32) * 64, '0'); }\n  // constructor(address signer, uint256 openCap, uint256 reservedCap, string base, string contractURI)\n  function args(sig, open, resv, base, curi) { var a = str(base), b = str(curi); return hex32(sig) + num32(open) + num32(resv) + num32(160) + num32(160 + a.length / 2) + a + b; }\n  async function call(to, data) { return pv.request({ method: 'eth_call', params: [{ to: to, data: data }, 'latest'] }); }\n  async function receipt(hash) { for (var i = 0; i < 90; i++) { var r = await pv.request({ method: 'eth_getTransactionReceipt', params: [hash] }); if (r) return r; await new Promise(function (ok) { setTimeout(ok, 2000); }); } return null; }\n  async function chain() { var c = await pv.request({ method: 'eth_chainId' }); if (String(c).toLowerCase() === CHAIN) return;\n    try { await pv.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: CHAIN }] }); }\n    catch (e) { await pv.request({ method: 'wallet_addEthereumChain', params: [{ chainId: CHAIN, chainName: 'Robinhood Chain', nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 }, rpcUrls: ['https://rpc.mainnet.chain.robinhood.com'], blockExplorerUrls: ['https://robinhoodchain.blockscout.com'] }] }); } }\n  $('base').value = location.origin + '/api/founders?id=';\n  fetch('/api/health').then(function (r) { return r.json(); }).then(function (h) { var f = h.founders || {}; if (f.signer && !$('sig').value) $('sig').value = f.signer; if (f.contract && !$('nft').value) $('nft').value = f.contract; }).catch(function () { });\n  $('conn').onclick = async function () {\n    if (!pv) { show('who', 'No wallet found. Open this page in your wallet app’s browser.', 'bad'); return; }\n    try { from = (await pv.request({ method: 'eth_requestAccounts' }))[0]; await chain(); show('who', 'Connected: <b>' + from + '</b> on Robinhood Chain', 'ok'); ['dep', 'refresh', 'pause', 'setEnd', 'move'].forEach(function (k) { $(k).disabled = false; }); if (isAddr($('nft').value.trim())) status(); }\n    catch (e) { show('who', 'Couldn’t connect: ' + esc(e.message || e), 'bad'); }\n  };\n  async function send(to, data, out) {\n    var h = await pv.request({ method: 'eth_sendTransaction', params: [{ from: from, to: to, data: data }] });\n    show(out, 'Sent… <a href=\"https://robinhoodchain.blockscout.com/tx/' + h + '\" target=\"_blank\" rel=\"noopener\">transaction</a>');\n    var r = await receipt(h); return r && r.status === '0x1' ? r : null;\n  }\n  $('dep').onclick = async function () {\n    var sig = $('sig').value.trim(), open = $('openCap').value.trim(), resv = $('resvCap').value.trim(), base = $('base').value.trim();\n    if (!isAddr(sig) || !/^\\d+$/.test(open) || !/^\\d+$/.test(resv) || +open + +resv < 1 || !/^https:\\/\\//.test(base)) { show('depOut', 'Check the signer address, the two pool sizes and metadata address (https://…).', 'bad'); return; }\n    try {\n      $('dep').disabled = true; show('depOut', 'Confirm the deployment in your wallet…');\n      var h = await pv.request({ method: 'eth_sendTransaction', params: [{ from: from, data: BYTECODE + args(sig, open, resv, base, base.replace(/\\?id=$/, '?contract=1')) }] });\n      show('depOut', 'Deploying… <a href=\"https://robinhoodchain.blockscout.com/tx/' + h + '\" target=\"_blank\" rel=\"noopener\">transaction</a>');\n      var r = await receipt(h);\n      if (!r || r.status !== '0x1' || !r.contractAddress) { show('depOut', 'The deployment failed. Check the transaction in the explorer.', 'bad'); $('dep').disabled = false; return; }\n      $('nft').value = r.contractAddress;\n      show('depOut', 'Collection deployed: <b>' + r.contractAddress + '</b><br>Save this address: it’s your <code>FOUNDERS_CONTRACT</code>.', 'ok'); status();\n    } catch (e) { show('depOut', 'Stopped: ' + esc(e.message || e), 'bad'); $('dep').disabled = false; }\n  };\n  async function status() {\n    var nft = $('nft').value.trim(); if (!isAddr(nft)) return show('stat', 'Enter the collection address.', 'bad');\n    try {\n      var n = async function (sel) { return parseInt(await call(nft, sel), 16); };\n      var sup = await n('0x18160ddd'), max = await n('0x32cb6b0c'), oc = await n('0xb507a381'), rc = await n('0x51c4f15c'), om = await n('0x0baa7400'), rm = await n('0x4f297ccc'), paused = (await n('0x5c975abb')) === 1, end = await n('0xea2b4ab2');\n      show('stat', '<b>' + sup.toLocaleString() + '</b> of ' + max.toLocaleString() + ' minted · minting <b class=\"' + (paused ? 'bad' : 'ok') + '\">' + (paused ? 'paused' : 'open') + '</b> · ' + (end ? 'ends ' + new Date(end * 1000).toLocaleString() : 'no end time') +\n        '<br>Open to every hero: <b>' + om.toLocaleString() + '</b> / ' + oc.toLocaleString() + ' · Held for giveaway winners: <b>' + rm.toLocaleString() + '</b> / ' + rc.toLocaleString());\n    } catch (e) { show('stat', 'Couldn’t read it: ' + esc(e.message || e), 'bad'); }\n  }\n  $('refresh').onclick = status;\n  $('pause').onclick = async function () {\n    var nft = $('nft').value.trim(); if (!isAddr(nft)) return show('ctlOut', 'Enter the collection address.', 'bad');\n    try { var paused = parseInt(await call(nft, '0x5c975abb'), 16) === 1; show('ctlOut', 'Confirm in your wallet…');\n      var ok = await send(nft, '0x16c38b3c' + num32(paused ? 0 : 1), 'ctlOut'); show('ctlOut', ok ? (paused ? 'Minting is open again.' : 'Minting is paused.') : 'That didn’t go through (only the owner can do this).', ok ? 'ok' : 'bad'); status(); }\n    catch (e) { show('ctlOut', 'Stopped: ' + esc(e.message || e), 'bad'); }\n  };\n  $('setEnd').onclick = async function () {\n    var nft = $('nft').value.trim(), v = $('end').value; if (!isAddr(nft)) return show('ctlOut', 'Enter the collection address.', 'bad');\n    var t = v ? Math.floor(new Date(v).getTime() / 1000) : 0;\n    try { show('ctlOut', 'Confirm in your wallet…'); var ok = await send(nft, '0xeb20614e' + num32(t), 'ctlOut'); show('ctlOut', ok ? (t ? 'The mint ends ' + new Date(t * 1000).toLocaleString() + '.' : 'The mint has no end time.') : 'That didn’t go through (only the owner can do this).', ok ? 'ok' : 'bad'); status(); }\n    catch (e) { show('ctlOut', 'Stopped: ' + esc(e.message || e), 'bad'); }\n  };\n  // move unclaimed giveaway spots into the open pool (after the giveaway, for spots no winner took)\n  $('move').onclick = async function () {\n    var nft = $('nft').value.trim(), n = $('moveN').value.trim(); if (!isAddr(nft)) return show('ctlOut', 'Enter the collection address.', 'bad');\n    if (!/^\\d+$/.test(n) || +n < 1) return show('ctlOut', 'Enter how many spots to move.', 'bad');\n    try { show('ctlOut', 'Confirm in your wallet…'); var ok = await send(nft, '0xad63d7a0' + num32(n), 'ctlOut'); show('ctlOut', ok ? n + ' giveaway spots moved to the open pool.' : 'That didn’t go through (only the owner can, and only unclaimed giveaway spots).', ok ? 'ok' : 'bad'); status(); }\n    catch (e) { show('ctlOut', 'Stopped: ' + esc(e.message || e), 'bad'); }\n  };\n  // X giveaway winners (stored by the game server; your tools pass is checked on every call)\n  async function api(body) { var r = await fetch('/api/tools', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'same-origin', body: JSON.stringify(body) }); var d = await r.json().catch(function () { return {}; }); if (!r.ok) throw new Error(d.msg || d.error || ('error ' + r.status)); return d; }\n  function winners(d, note) {\n    var list = d.winners || [];\n    $('wCount').innerHTML = '<b>' + list.length.toLocaleString() + '</b> of ' + (d.cap || 1000).toLocaleString() + ' giveaway spots given out' + (note ? '<br>' + note : '');\n    $('wList').innerHTML = list.length ? list.map(function (w) { return '<span class=\"w\">' + esc(w.name) + ' <small>#' + esc(w.no) + '</small></span>'; }).join('') : '<i>No winners yet.</i>';\n  }\n  function note(d) { var p = []; if (d.done && d.done.length) p.push('<span class=\"ok\">Done: ' + d.done.map(esc).join(', ') + '</span>'); if (d.missing && d.missing.length) p.push('<span class=\"bad\">No hero named: ' + d.missing.map(esc).join(', ') + '</span>'); if (d.skipped && d.skipped.length) p.push('<span class=\"bad\">Full, not added: ' + d.skipped.map(esc).join(', ') + '</span>'); return p.join('<br>'); }\n  function loadW() { api({ action: 'winners' }).then(function (d) { winners(d); }).catch(function (e) { $('wCount').innerHTML = '<span class=\"bad\">' + esc(e.message) + ' (run supabase/founders-giveaway.sql?)</span>'; }); }\n  $('wAdd').onclick = function () { api({ action: 'winners_add', names: $('wNames').value }).then(function (d) { $('wNames').value = ''; winners(d, note(d)); }).catch(function (e) { $('wCount').innerHTML = '<span class=\"bad\">' + esc(e.message) + '</span>'; }); };\n  $('wDel').onclick = function () { api({ action: 'winners_remove', names: $('wNames').value }).then(function (d) { $('wNames').value = ''; winners(d, note(d)); }).catch(function (e) { $('wCount').innerHTML = '<span class=\"bad\">' + esc(e.message) + '</span>'; }); };\n  loadW();\n})();\n","index.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"robots\" content=\"noindex\">\n<title>Lanternhold owner tools</title>\n<style>\n:root{--ink:#1a1c2c;--bg:#0f1020;--panel:#20243a;--line:#3d4a66;--text:#eef1f5;--muted:#a9bdcc;--gold:#ffcd75;--green:#a7f070;--red:#ef7d57}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\nmain{max-width:640px;margin:0 auto;padding:20px 16px 60px}h1{color:var(--gold);font-size:26px;margin:0 0 4px}h2{font-size:18px;margin:26px 0 6px;color:var(--gold)}\np,li{color:var(--muted)}b{color:var(--text)}label{display:block;margin:12px 0 4px;font-weight:600}\ninput{width:100%;font:15px ui-monospace,Menlo,monospace;padding:10px;background:var(--panel);color:var(--text);border:2px solid var(--line)}\nbutton{font:600 16px system-ui;padding:12px 16px;margin-top:12px;background:#3b5dc9;color:#fff;border:2px solid var(--ink);cursor:pointer;width:100%}button:disabled{opacity:.5}\n.box{background:var(--panel);border:2px solid var(--line);padding:12px 14px;margin:10px 0;word-break:break-all}.ok{color:var(--green)}.bad{color:var(--red)}code{color:var(--gold)}\n</style></head><body><main>\n</head><body><main>\n<h1>Owner tools</h1>\n<div class=\"box ok\" id=\"who\">Signed in.</div>\n<h2>Tools</h2>\n<p><a href=\"/tools/vault.html\" style=\"color:#ffcd75\">Rewards vault</a>: deploy, fund in phases, tune the daily limits.</p>\n<p><a href=\"/tools/founders.html\" style=\"color:#ffcd75\">Founder’s Lantern</a>: deploy the NFT, pause, set the end time.</p>\n<button id=\"out\">Sign out</button>\n</main><script src=\"/tools/index.js\"></script></body></html>\n","index.js":"// Owner tools home: who's signed in, and sign out.\n(function () {\n  var $ = function (id) { return document.getElementById(id); };\n  var post = function (b) { return fetch('/api/tools', { method: 'POST', headers: { 'content-type': 'application/json', 'x-lh': '1' }, body: JSON.stringify(b), credentials: 'same-origin' }).then(function (r) { return r.json(); }); };\n  post({ action: 'whoami' }).then(function (d) { if (d.address) $('who').innerHTML = 'Signed in as <b>' + d.address + '</b>'; });\n  $('out').onclick = function () { post({ action: 'logout' }).then(function () { location.href = '/tools'; }); };\n})();\n","login.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"robots\" content=\"noindex\">\n<title>Lanternhold owner tools</title>\n<style>\n:root{--ink:#1a1c2c;--bg:#0f1020;--panel:#20243a;--line:#3d4a66;--text:#eef1f5;--muted:#a9bdcc;--gold:#ffcd75;--green:#a7f070;--red:#ef7d57}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\nmain{max-width:640px;margin:0 auto;padding:20px 16px 60px}h1{color:var(--gold);font-size:26px;margin:0 0 4px}h2{font-size:18px;margin:26px 0 6px;color:var(--gold)}\np,li{color:var(--muted)}b{color:var(--text)}label{display:block;margin:12px 0 4px;font-weight:600}\ninput{width:100%;font:15px ui-monospace,Menlo,monospace;padding:10px;background:var(--panel);color:var(--text);border:2px solid var(--line)}\nbutton{font:600 16px system-ui;padding:12px 16px;margin-top:12px;background:#3b5dc9;color:#fff;border:2px solid var(--ink);cursor:pointer;width:100%}button:disabled{opacity:.5}\n.box{background:var(--panel);border:2px solid var(--line);padding:12px 14px;margin:10px 0;word-break:break-all}.ok{color:var(--green)}.bad{color:var(--red)}code{color:var(--gold)}\n</style></head><body><main>\n</head><body><main>\n<h1>Owner tools</h1>\n<p>Locked. Only the Lanternhold admin wallets can get in. Open this page in your wallet app’s browser (MetaMask, Rabby…), connect an admin wallet and sign the sign-in message. Signing is free: it isn’t a transaction.</p>\n<div class=\"box\" id=\"who\">Not connected.</div>\n<button id=\"go\">Connect and sign in</button>\n</main><script src=\"/tools/login.js\"></script></body></html>\n","login.js":"// Sign in to the owner tools with an admin wallet (Sign-In with Ethereum). The server decides who's allowed.\n(function () {\n  var $ = function (id) { return document.getElementById(id); };\n  var show = function (html, cls) { var e = $('who'); e.className = 'box ' + (cls || ''); e.innerHTML = html; };\n  async function post(b) { var r = await fetch('/api/tools', { method: 'POST', headers: { 'content-type': 'application/json', 'x-lh': '1' }, body: JSON.stringify(b), credentials: 'same-origin' }); var d = {}; try { d = await r.json(); } catch (e) { } return { ok: r.ok, d: d }; }\n  $('go').onclick = async function () {\n    var pv = window.ethereum; if (!pv) { show('No wallet found. Open this page in your wallet app’s browser.', 'bad'); return; }\n    try {\n      $('go').disabled = true;\n      var addr = (await pv.request({ method: 'eth_requestAccounts' }))[0];\n      show('Checking ' + addr + '…');\n      var n = await post({ action: 'nonce', address: addr });\n      if (!n.ok) { show(n.d.msg || 'Not allowed.', 'bad'); $('go').disabled = false; return; }\n      show('Sign the message in your wallet…');\n      var hex = '0x' + Array.from(new TextEncoder().encode(n.d.message)).map(function (b) { return b.toString(16).padStart(2, '0'); }).join('');\n      var sig = await pv.request({ method: 'personal_sign', params: [hex, addr] });\n      var v = await post({ action: 'verify', message: n.d.message, signature: sig });\n      if (!v.ok) { show(v.d.msg || 'Sign-in failed.', 'bad'); $('go').disabled = false; return; }\n      show('Signed in as <b>' + v.d.address + '</b>', 'ok'); location.reload();\n    } catch (e) { show('Stopped: ' + (e.message || e), 'bad'); $('go').disabled = false; }\n  };\n})();\n","vault.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"robots\" content=\"noindex\">\n<title>Rewards vault setup</title>\n<style>\n:root{--ink:#1a1c2c;--bg:#0f1020;--panel:#20243a;--line:#3d4a66;--text:#eef1f5;--muted:#a9bdcc;--gold:#ffcd75;--green:#a7f070;--red:#ef7d57}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\nmain{max-width:640px;margin:0 auto;padding:20px 16px 60px}h1{color:var(--gold);font-size:26px;margin:0 0 4px}h2{font-size:18px;margin:26px 0 6px;color:var(--gold)}\np,li{color:var(--muted)}b{color:var(--text)}label{display:block;margin:12px 0 4px;font-weight:600}\ninput{width:100%;font:15px ui-monospace,Menlo,monospace;padding:10px;background:var(--panel);color:var(--text);border:2px solid var(--line)}\nbutton{font:600 16px system-ui;padding:12px 16px;margin-top:12px;background:#3b5dc9;color:#fff;border:2px solid var(--ink);cursor:pointer;width:100%}button:disabled{opacity:.5}\n.box{background:var(--panel);border:2px solid var(--line);padding:12px 14px;margin:10px 0;word-break:break-all}.ok{color:var(--green)}.bad{color:var(--red)}code{color:var(--gold)}\n</style></head><body><main>\n<p style=\"margin:0 0 10px\"><a href=\"/tools\" style=\"color:#a9bdcc\">← Owner tools</a></p>\n<h1>Rewards vault setup</h1>\n<p>For the Lanternhold owner. Open this page in your wallet app’s browser (MetaMask, Rabby…) with the wallet that holds the rewards tokens, on Robinhood Chain.</p>\n<div class=\"box\" id=\"who\">Not connected.</div>\n<button id=\"conn\">Connect wallet</button>\n\n<h2>1. Deploy the vault</h2>\n<p>Creates the rewards vault and <b>locks</b> it: until the unlock date, tokens can only leave through player claims. Nobody, you included, can withdraw them. You only deploy it once: fund it in phases by sending more tokens to it any time (step 2). You’ll be its owner: you can pause claims, tune the daily limits any time (step 4), and replace the signer (it takes over 2 days after you propose it, so it’s always public first).</p>\n<label for=\"tok\">Token contract address</label><input id=\"tok\" placeholder=\"0x…\">\n<label for=\"sig\">Signer address (the wallet whose private key is CLAIM_SIGNER_KEY in Vercel)</label><input id=\"sig\" placeholder=\"0x…\">\n<label for=\"cap\">Daily payout limit (tokens, gross)</label><input id=\"cap\" value=\"500000\">\n<label for=\"bps\">…and at most this % of the vault per day (the emptier the vault, the less it can pay)</label><input id=\"bps\" value=\"1\">\n<label for=\"unlock\">Locked until (no withdrawals before this date; can never be changed)</label><input id=\"unlock\" type=\"date\">\n<button id=\"dep\" disabled>Deploy vault</button>\n<div class=\"box\" id=\"depOut\" hidden></div>\n\n<h2>2. Fund it (and top it up later)</h2>\n<p>Sends tokens from this wallet into the vault. Fund in phases: send more any time, to the same vault. The game reads the vault’s balance, so a top-up raises the daily rewards from the next day (UTC).</p>\n<label for=\"vault\">Vault address</label><input id=\"vault\" placeholder=\"0x… (filled in after deploying)\">\n<label for=\"amt\">Amount (tokens)</label><input id=\"amt\" value=\"10000000\">\n<button id=\"fund\" disabled>Send tokens to the vault</button>\n<div class=\"box\" id=\"fundOut\" hidden></div>\n\n<h2>3. Check the lock</h2>\n<p>Anyone can check it on the explorer: the vault’s <code>unlockAt</code>, <code>maxDailyCap</code>, <code>signer</code> and its token balance.</p>\n<div class=\"box\" id=\"lockOut\">Deploy or enter the vault address, then tap below.</div>\n<button id=\"chk\" disabled>Check the vault</button>\n\n<h2>4. Tune the daily limits (any time)</h2>\n<p>If rewards drain too fast, lower these. The game’s own daily budget is set in Vercel (<code>REWARDS_DAY_RATE</code>); these are the vault’s safety limits on top.</p>\n<label for=\"cap2\">Daily payout limit (tokens, gross)</label><input id=\"cap2\" value=\"500000\">\n<label for=\"bps2\">…and at most this % of the vault per day</label><input id=\"bps2\" value=\"1\">\n<button id=\"lim\" disabled>Update the daily limits</button>\n<div class=\"box\" id=\"limOut\" hidden></div>\n\n<h2>5. Turn it on</h2>\n<p>In Vercel → Settings → Environment Variables: <code>CLAIM_CONTRACT</code> = the vault address, <code>CLAIM_SIGNER_KEY</code> = the signer’s private key (mark it <b>Sensitive</b>), and <code>REWARDS_ON</code> = <code>1</code>. Then redeploy and open <code>/api/health</code>: <code>rewards.claims</code> should be <code>true</code>.</p>\n</main><script src=\"/tools/vault.js\"></script></body></html>\n","vault.js":"// Owner tool: deploy the rewards vault (contracts/LanternRewards.sol) and fund it, from the owner's own wallet.\n(function () {\n  var BYTECODE = '', CHAIN = '0x1237', $ = function (id) { return document.getElementById(id); };\n  var pv = window.ethereum, from = null;\n  var hex32 = function (h) { return h.replace(/^0x/, '').toLowerCase().padStart(64, '0'); };\n  var isAddr = function (a) { return /^0x[0-9a-fA-F]{40}$/.test(a); };\n  var show = function (id, html, cls) { var e = $(id); e.hidden = false; e.className = 'box ' + (cls || ''); e.innerHTML = html; };\n  function units(amount, dec) { var p = String(amount).trim().split('.'); var frac = (p[1] || '').slice(0, dec).padEnd(dec, '0'); return BigInt(p[0] || '0') * 10n ** BigInt(dec) + BigInt(frac || '0'); }\n  async function call(to, data) { return pv.request({ method: 'eth_call', params: [{ to: to, data: data }, 'latest'] }); }\n  async function decimals(tok) { var r = await call(tok, '0x313ce567'); return parseInt(r, 16); }\n  async function receipt(hash) { for (var i = 0; i < 90; i++) { var r = await pv.request({ method: 'eth_getTransactionReceipt', params: [hash] }); if (r) return r; await new Promise(function (ok) { setTimeout(ok, 2000); }); } return null; }\n  async function chain() { var c = await pv.request({ method: 'eth_chainId' }); if (String(c).toLowerCase() === CHAIN) return;\n    try { await pv.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: CHAIN }] }); }\n    catch (e) { await pv.request({ method: 'wallet_addEthereumChain', params: [{ chainId: CHAIN, chainName: 'Robinhood Chain', nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 }, rpcUrls: ['https://rpc.mainnet.chain.robinhood.com'], blockExplorerUrls: ['https://robinhoodchain.blockscout.com'] }] }); } }\n  // prefill from the site: the token's address and the signer's (public) address\n  fetch('/api/config').then(function (r) { return r.json(); }).then(function (c) { if (c.token && c.token.ca && !$('tok').value) $('tok').value = c.token.ca; }).catch(function () { });\n  fetch('/api/health').then(function (r) { return r.json(); }).then(function (h) { var x = h.rewards || {}; if (x.signer && !$('sig').value) $('sig').value = x.signer; if (x.contract && !$('vault').value) $('vault').value = x.contract; }).catch(function () { });\n  $('conn').onclick = async function () {\n    if (!pv) { show('who', 'No wallet found. Open this page in your wallet app’s browser.', 'bad'); return; }\n    try { from = (await pv.request({ method: 'eth_requestAccounts' }))[0]; await chain(); show('who', 'Connected: <b>' + from + '</b> on Robinhood Chain', 'ok'); $('dep').disabled = $('fund').disabled = $('chk').disabled = $('lim').disabled = false; }\n    catch (e) { show('who', 'Couldn’t connect: ' + (e.message || e), 'bad'); }\n  };\n  (function () { var d = new Date(); d.setFullYear(d.getFullYear() + 1); $('unlock').value = d.toISOString().slice(0, 10); })();   // default: locked for a year\n  function pctBps(v) { var n = Math.round(parseFloat(v) * 100); return n >= 1 && n <= 1000 ? n : 0; }   // 1% = 100 bps\n  function unlockTs() { var v = $('unlock').value; return v ? Math.floor(new Date(v + 'T00:00:00Z').getTime() / 1000) : 0; }\n  $('dep').onclick = async function () {\n    var tok = $('tok').value.trim(), sig = $('sig').value.trim(), cap = $('cap').value.trim(), bps = pctBps($('bps').value), until = unlockTs();\n    if (!isAddr(tok) || !isAddr(sig) || !/^\\d+(\\.\\d+)?$/.test(cap) || !bps) { show('depOut', 'Check the token address, signer address, daily limit and % (0.01 to 10).', 'bad'); return; }\n    if (!(until > Date.now() / 1000 + 86400)) { show('depOut', 'Pick an unlock date in the future.', 'bad'); return; }\n    if (!confirm('Lock the vault until ' + new Date(until * 1000).toUTCString().slice(0, 16) + '? This date can never be changed.')) return;\n    try {\n      $('dep').disabled = true; show('depOut', 'Reading the token…');\n      var dec = await decimals(tok), data = BYTECODE + hex32(tok) + hex32(sig) + units(cap, dec).toString(16).padStart(64, '0') + BigInt(bps).toString(16).padStart(64, '0') + BigInt(until).toString(16).padStart(64, '0');\n      show('depOut', 'Confirm the deployment in your wallet…');\n      var h = await pv.request({ method: 'eth_sendTransaction', params: [{ from: from, data: data }] });\n      show('depOut', 'Deploying… <a href=\"https://robinhoodchain.blockscout.com/tx/' + h + '\" target=\"_blank\" rel=\"noopener\">transaction</a>');\n      var r = await receipt(h);\n      if (!r || r.status !== '0x1' || !r.contractAddress) { show('depOut', 'The deployment failed. Check the transaction in the explorer.', 'bad'); $('dep').disabled = false; return; }\n      $('vault').value = r.contractAddress;\n      show('depOut', 'Vault deployed: <b>' + r.contractAddress + '</b><br>Save this address: it’s your <code>CLAIM_CONTRACT</code>. Next, fund it.', 'ok');\n    } catch (e) { show('depOut', 'Stopped: ' + (e.message || e), 'bad'); $('dep').disabled = false; }\n  };\n  $('chk').onclick = async function () {\n    var vault = $('vault').value.trim(), tok = $('tok').value.trim(); if (!isAddr(vault)) { show('lockOut', 'Enter the vault address.', 'bad'); return; }\n    try {\n      var un = parseInt(await call(vault, '0xaa5dec6f'), 16), mx = BigInt(await call(vault, '0xeb339391')), bp = parseInt(await call(vault, '0xc8b07bbc'), 16), tl = BigInt(await call(vault, '0xa47d0b6d')), sg = '0x' + (await call(vault, '0x238ac933')).slice(26), dec = await decimals(tok), bal = BigInt(await call(tok, '0x70a08231' + hex32(vault)));\n      var f = function (v) { return (v / 10n ** BigInt(dec)).toLocaleString(); };\n      show('lockOut', 'Holds <b>' + f(bal) + '</b> tokens · locked until <b>' + new Date(un * 1000).toUTCString().slice(0, 16) + '</b> · daily limit <b>' + f(mx) + '</b> or <b>' + (bp / 100) + '%</b> of the vault · can still pay today <b>' + f(tl) + '</b> · signer ' + sg, 'ok');\n    } catch (e) { show('lockOut', 'Couldn’t read it: ' + (e.message || e), 'bad'); }\n  };\n  $('lim').onclick = async function () {\n    var vault = $('vault').value.trim(), tok = $('tok').value.trim(), cap = $('cap2').value.trim(), bps = pctBps($('bps2').value);\n    if (!isAddr(vault) || !isAddr(tok) || !/^\\d+(\\.\\d+)?$/.test(cap) || !bps) { show('limOut', 'Check the vault address, the limit and the % (0.01 to 10).', 'bad'); return; }\n    try { var dec = await decimals(tok); show('limOut', 'Confirm in your wallet…');\n      var h = await pv.request({ method: 'eth_sendTransaction', params: [{ from: from, to: vault, data: '0x9883cffe' + units(cap, dec).toString(16).padStart(64, '0') + BigInt(bps).toString(16).padStart(64, '0') }] });\n      var r = await receipt(h); show('limOut', r && r.status === '0x1' ? 'Updated: at most ' + Number(cap).toLocaleString() + ' tokens or ' + (bps / 100) + '% of the vault per day.' : 'That didn’t go through (only the owner can do this).', r && r.status === '0x1' ? 'ok' : 'bad');\n    } catch (e) { show('limOut', 'Stopped: ' + (e.message || e), 'bad'); }\n  };\n  $('fund').onclick = async function () {\n    var tok = $('tok').value.trim(), vault = $('vault').value.trim(), amt = $('amt').value.trim();\n    if (!isAddr(tok) || !isAddr(vault) || !/^\\d+(\\.\\d+)?$/.test(amt)) { show('fundOut', 'Check the token address, vault address and amount.', 'bad'); return; }\n    try {\n      $('fund').disabled = true; var dec = await decimals(tok);\n      var data = '0xa9059cbb' + hex32(vault) + units(amt, dec).toString(16).padStart(64, '0');   // transfer(vault, amount)\n      show('fundOut', 'Confirm the transfer of ' + Number(amt).toLocaleString() + ' tokens in your wallet…');\n      var h = await pv.request({ method: 'eth_sendTransaction', params: [{ from: from, to: tok, data: data }] });\n      var r = await receipt(h);\n      show('fundOut', r && r.status === '0x1' ? 'Sent. The vault holds the rewards pool. <a href=\"https://robinhoodchain.blockscout.com/tx/' + h + '\" target=\"_blank\" rel=\"noopener\">transaction</a>' : 'The transfer failed.', r && r.status === '0x1' ? 'ok' : 'bad');\n      $('fund').disabled = false;\n    } catch (e) { show('fundOut', 'Stopped: ' + (e.message || e), 'bad'); $('fund').disabled = false; }\n  };\n})();\n"};
